Given an array arr[] consisting of both positive and negative integers, find the length of the longest subarray whose elements sum is zero. A subarray is a contiguous part of an array, formed by selecting one or more consecutive elements while maintaining their original order.Examples:Input: arr[] = [15, -2, 2, -8, 1, 7, 10]Output: 5Explanation: The longest subarray with sum equals to 0 is [-2, 2, -8, 1, 7].Input: arr[] = [1, 2, 3]Output: 0Explanation: There is no subarray with 0 sum.Input:  arr[] = [1, 0, 3]Output:  1Explanation: The longest sub-array with sum equal to 0 is [0].Try It YourselfTable of Content[Naive Approach] Iterating over all subarrays - O(n^2) Time and O(1) Space[Expected Approach] Using Hashmap and Prefix Sum - O(n) Time and O(n) Space[Naive Approach] Iterating over all subarrays - O(n2) Time and O(1) SpaceWe try all possible subarrays using two nested loops. For each subarray, we calculate its sum, and if the sum is zero, we update the maximum length accordingly.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int maxLength(vector<int>& arr) {  
    int n = arr.size();
    int maxLen = 0; 

    // Loop through each starting point
    for (int i = 0; i < n; i++) {
        int currSum = 0;

        // Try all subarrays starting from 'i'
        for (int j = i; j < n; j++) {
            currSum += arr[j]; 

            // as currSum becomes 0, update maxLen
            if (currSum == 0)
                maxLen = max(maxLen, j - i + 1);
        }
    }
    return maxLen;
}

int main() {
    vector<int> arr = {15, -2, 2, -8, 1, 7, 10};
    cout << maxLength(arr) << endl;
    return 0;
}


